import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
class AuthScreen extends StatefulWidget{const AuthScreen({super.key});@override State<AuthScreen> createState()=>_AuthScreenState();}
class _AuthScreenState extends State<AuthScreen>{final email=TextEditingController(),password=TextEditingController();String? message;bool create=false;
Future<void> submit()async{try{if(create){await Supabase.instance.client.auth.signUp(email:email.text.trim(),password:password.text);}else{await Supabase.instance.client.auth.signInWithPassword(email:email.text.trim(),password:password.text);}setState(()=>message=create?'Account created. Check email if confirmation is enabled.':'Signed in.');}catch(e){setState(()=>message=e.toString());}}
@override void dispose(){email.dispose();password.dispose();super.dispose();}
@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:ListView(padding:const EdgeInsets.all(24),children:[const SizedBox(height:50),const Text('ConsistiFit',style:TextStyle(fontSize:34,fontWeight:FontWeight.w900)),const Text('Build consistency. Earn your rank.',style:TextStyle(color:Colors.white60)),const SizedBox(height:28),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),const SizedBox(height:16),FilledButton(onPressed:submit,child:Text(create?'Create account':'Sign in')),TextButton(onPressed:()=>setState(()=>create=!create),child:Text(create?'Already have an account? Sign in':'New here? Create account')),if(message!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(message!))])));}
}
